TaskEnvironmental.Args._fields_ = []


class TaskGnss:
    ID = 4

    class Logging:
        LLHA = BIT(0)
        """Log latitude, longitude, height and accuracy"""
        FIX_INFO = BIT(1)
        """Log fix information"""
        PVT = BIT(7)
        """Log maximum information position, velocity and time"""

    class Constellations:
        GPS = BIT(0)
        """GPS constellation"""
        GLONASS = BIT(1)
        """GLONASS constellation"""
        GALILEO = BIT(2)
        """Galileo constellation"""
        BEIDOU = BIT(3)
        """BeiDou constellation"""
        QZSS = BIT(4)
        """QZSS constellation"""
        IRNSS = BIT(5)
        """IRNSS constellation"""
        SBAS = BIT(6)
        """SBAS constellation"""
        IMES = BIT(7)
        """IMES constellation"""

    class Flags:
        RUN_FOREVER = 0
        """Runs until terminated by the scheduler"""
        RUN_TO_LOCATION_FIX = 1
        """Terminates when the location is known to specified accuracy"""
        RUN_TO_TIME_SYNC = 2
        """Terminates when the time has been synced"""
        RUN_MASK = 3
        """Run-until mask"""
        LOW_POWER_MODE = 0x00
        """Run GNSS in low power mode"""
        PERFORMANCE_MODE = BIT(7)
        """Run GNSS in performance mode"""

    class PlateauArgs(ctypes.LittleEndianStructure):
        _pack_ = 1

    class RunToFixArgs(ctypes.LittleEndianStructure):
        _pack_ = 1

    class LowPowerArgs(ctypes.LittleEndianStructure):
        _pack_ = 1

    class ModeArgs(ctypes.Union):
        _pack_ = 1

    class Args(ctypes.LittleEndianStructure):
        _pack_ = 1
        _anonymous_ = ("mode",)


TaskGnss.PlateauArgs._fields_ = [
    ("min_accuracy_m", ctypes.c_uint8),
    ("min_accuracy_improvement_m", ctypes.c_uint8),
    ("timeout", ctypes.c_uint8),
]
TaskGnss.RunToFixArgs._fields_ = [
    ("any_fix_timeout", ctypes.c_uint8),
    ("fix_plateau", TaskGnss.PlateauArgs),
]
TaskGnss.LowPowerArgs._fields_ = [
    ("acquisition_timeout", ctypes.c_uint16),
    ("search_period", ctypes.c_uint16),
]
TaskGnss.ModeArgs._fields_ = [
    ("run_to_fix", TaskGnss.RunToFixArgs),
    ("low_power", TaskGnss.LowPowerArgs),
]
TaskGnss.Args._fields_ = [
    ("constellations", ctypes.c_uint8),
    ("flags", ctypes.c_uint8),
    ("accuracy_m", ctypes.c_uint16),
    ("position_dop", ctypes.c_uint16),
    ("mode", TaskGnss.ModeArgs),
    ("dynamic_model", ctypes.c_uint8),
]


class TaskNetworkScan:
    ID = 5

    class Logging:
        LTE_CELLS = BIT(0)
        """Log LTE TAC cells"""
        WIFI_AP = BIT(1)
        """Log Wi-Fi access point information"""
        COUNT = BIT(2)
        """Log network scan count"""

    class Flags:
        LTE_CELLS = BIT(0)
        """Scan nearby LTE cells"""
        WIFI_CELLS = BIT(1)
        """Scan nearby Wi-Fi access points"""
        SKIP_LTE_IF_WIFI_GOOD = BIT(7)
        """Skip LTE scan if desired_aps Wi-Fi access points are found"""

    class WifiArgs(ctypes.LittleEndianStructure):
        class Flags:
            INCLUDE_DUPLICATES = BIT(0)
            """Report multiple networks from the same access point"""
            SCAN_PROGRESSIVE = BIT(1)
            """Scan Wi-Fi channels over multiple calls in order of most to least common"""
            SCAN_ACTIVE = BIT(2)
            """Use active scanning"""
            INCLUDE_LOCALLY_ADMINISTERED = BIT(3)
            """Report networks using locally administered BSSIDs"""

        _pack_ = 1

    class LteArgs(ctypes.LittleEndianStructure):
        _pack_ = 1

    class Args(ctypes.LittleEndianStructure):
        _pack_ = 1


TaskNetworkScan.WifiArgs._fields_ = [
    ("flags", ctypes.c_uint8),
    ("desired_aps", ctypes.c_uint8),
    ("max_aps", ctypes.c_uint8),
]
TaskNetworkScan.LteArgs._fields_ = [
    ("desired_cells", ctypes.c_uint8),
]
TaskNetworkScan.Args._fields_ = [
    ("flags", ctypes.c_uint8),
    ("wifi", TaskNetworkScan.WifiArgs),
    ("lte", TaskNetworkScan.LteArgs),
]


class TaskBtScanner:
    ID = 6

    class Logging:
        INFUSE_BT = BIT(0)
