class TaskArguments(ctypes.Union):
    TASK_IDS = {
        "tdf_logger": TaskTdfLogger.ID,
        "tdf_logger_alt1": TaskTdfLogger.ALT1_ID,
        "tdf_logger_alt2": TaskTdfLogger.ALT2_ID,
        "imu": TaskImu.ID,
        "battery": TaskBattery.ID,
        "environmental": TaskEnvironmental.ID,
        "gnss": TaskGnss.ID,
        "network_scan": TaskNetworkScan.ID,
        "bt_scanner": TaskBtScanner.ID,
        "soc_temperature": TaskSocTemperature.ID,
        "audio_dmic": TaskAudioDmic.ID,
    }

    TASK_ARG_FIELDS = {
        TaskTdfLogger.ID: "tdf_logger",
        TaskTdfLogger.ALT1_ID: "tdf_logger",
        TaskTdfLogger.ALT2_ID: "tdf_logger",
        TaskImu.ID: "imu",
        TaskBattery.ID: "battery",
        TaskEnvironmental.ID: "environmental",
        TaskGnss.ID: "gnss",
        TaskNetworkScan.ID: "network_scan",
        TaskBtScanner.ID: "bt_scanner",
        TaskSocTemperature.ID: "soc_temperature",
        TaskAudioDmic.ID: "audio_dmic",
    }

    TASK_LOGGING_CLASSES = {
        TaskTdfLogger.ID: TaskTdfLogger.Tdfs,
        TaskTdfLogger.ALT1_ID: TaskTdfLogger.Tdfs,
        TaskTdfLogger.ALT2_ID: TaskTdfLogger.Tdfs,
        TaskImu.ID: TaskImu.Logging,
        TaskBattery.ID: TaskBattery.Logging,
        TaskEnvironmental.ID: TaskEnvironmental.Logging,
        TaskGnss.ID: TaskGnss.Logging,
        TaskNetworkScan.ID: TaskNetworkScan.Logging,
        TaskBtScanner.ID: TaskBtScanner.Logging,
        TaskSocTemperature.ID: TaskSocTemperature.Logging,
        TaskAudioDmic.ID: TaskAudioDmic.Logging,
    }

    _pack_ = 1
    _fields_ = [
        ("raw", ctypes.c_uint8 * 17),
        ("tdf_logger", TaskTdfLogger.Args),
        ("imu", TaskImu.Args),
        ("battery", TaskBattery.Args),
        ("environmental", TaskEnvironmental.Args),
        ("gnss", TaskGnss.Args),
        ("network_scan", TaskNetworkScan.Args),
        ("bt_scanner", TaskBtScanner.Args),
        ("soc_temperature", TaskSocTemperature.Args),
        ("audio_dmic", TaskAudioDmic.Args),
    ]


if __name__ == "__main__":
    print("Task IDs:")
    for name, task_id in TaskArguments.TASK_IDS.items():
        print(f"  {name}: {task_id}")
    print("Task argument sizes:")
    for name, field_type in TaskArguments._fields_:
        print(f"  {name}: {ctypes.sizeof(field_type)}")
    print(f"TaskArguments size: {ctypes.sizeof(TaskArguments)}")
